fn run_text(first: Int, last: Int) -> List[Str] {
  if last - first >= 2 {
    return [first.to_str() + "-" + last.to_str()]
  }
  if last - first == 1 {
    return [first.to_str(), last.to_str()]
  }
  return [first.to_str()]
}

pub fn ranges(xs: List[Int]) -> Str {
  let sorted_unique = xs.unique().sort()
  var parts: List[Str] = []
  var start = 0
  var prev = 0
  var started = false
  for x in sorted_unique {
    if not started {
      start = x
      started = true
    } else if x != prev + 1 {
      parts = parts.concat(run_text(start, prev))
      start = x
    }
    prev = x
  }
  if started {
    parts = parts.concat(run_text(start, prev))
  }
  return parts.join(",")
}
